pub fn find_by_formula_id(formula_id: &str) -> Option<&'static FormulaRegistryEntry> {
    FORMULA_REGISTRY
        .iter()
        .find(|entry| entry.formula_id == formula_id)
}

pub fn find_by_alias(alias: &str) -> Option<&'static FormulaRegistryEntry> {
    FORMULA_REGISTRY
        .iter()
        .find(|entry| entry.aliases.iter().any(|candidate| *candidate == alias))
}
